import math
def priority(task, state, a=2.0, k=0.8):
    est = max(task.estimated_runtime, 1e-6)
    slack = task.due - state.now - est
    value_density = task.weight / (est * max(task.resource_need, 1e-6))
    if slack < 0.0:
        remaining = 1.0 + slack / (2.0 * est)
        if remaining <= 0.0:
            return -1e9
        return a * value_density * remaining
    else:
        urgency = math.exp(-slack / (k * max(state.mean_est, 1e-6)))
        return -slack + a * value_density * urgency

import math
def priority(task, state, thresh=0.8, a=1.5, k=1.0):
    est = max(task.estimated_runtime, 1e-6)
    slack = task.due - state.now - est
    value_density = task.weight / (est * max(task.resource_need, 1e-6))
    load = state.queue_work / max(state.capacity * state.mean_est, 1e-6)
    if load > thresh:
        return -slack + a * value_density * math.exp(-max(0.0, slack) / (k * max(state.mean_est, 1e-6)))
    else:
        return -slack + a * value_density

