    est = max(task.estimated_runtime, 1e-6)
    need = max(task.resource_need, 1e-6)
    slack = task.due - state.now - est
    value_density = task.weight / (est * need)
    load = state.queue_work / max(state.capacity * state.mean_est, 1e-6)
    wait = state.now - task.release
    if load > thresh:
        if slack < 0.0:
            remaining = max(0.0, 1.0 + slack / (2.0 * est))
            return -slack + a * value_density * remaining + b * wait / est
        urgency = math.exp(-slack / (k * max(state.mean_est, 1e-6)))
        return -slack + a * value_density * urgency + b * wait / est
    else:
