import math
def priority(task, state, a=1.0, b=0.1, c=0.5, k=1.0, align=1.0, variant=1.2, sv=1.4, premium=1.2):
    est = max(task.estimated_runtime, 1e-6)
    need = max(task.resource_need, 1e-6)
    load = state.queue_work / max(state.capacity * state.mean_est, 1e-6)
    if task.task_type == 'alignment':
        type_risk = align
    elif task.task_type == 'variant_calling':
        type_risk = variant
    else:
        type_risk = sv
    tenant = premium if task.tenant == 'premium' else 1.0
    eff_est = est * type_risk * (1.0 + c * load)
    slack = task.due - state.now - eff_est
    wait = state.now - task.release
    value_density = tenant * task.weight / (est * need)
    if slack <= 0.0:
        decay = max(0.0, 1.0 + slack / (2.0 * est * type_risk))
        return a * value_density * decay + b * wait / est - slack / eff_est
    else:
        urgency = math.exp(-slack / (k * max(state.mean_est, 1e-6)))
        return a * value_density * urgency * (1.0 + b * wait / est)

