import math
def priority(task, state, k=0.5, m=2.0, f_vc=1.0, f_sv=1.0, f_prem=1.0, rho=0.0):
    p = max(task.estimated_runtime, 1e-6)
    if task.task_type == 'variant_calling':
        p *= f_vc
    elif task.task_type == 'sv_calling':
        p *= f_sv
    p = max(p, 1e-6)
    r = max(task.resource_need, 1e-6)
    now = state.now
    mean = max(state.mean_est, 1e-6)
    slack = task.due - p - now
    atc = task.weight / p * math.exp(-max(0.0, slack) / (max(k, 1e-6) * mean))
    if task.tenant == 'premium':
        atc *= f_prem
    if slack < 0.0:
        recover = max(0.0, (task.due + p - now) / (2.0 * p))
        if recover <= 0.0:
            return 0.0
        atc *= (1.0 + m * (-slack) / p) * recover
    return atc / (r ** rho)

import math
def priority(task, state, k=1.0, a=2.0, b=0.5, rho=0.0):
    p = max(task.estimated_runtime, 1e-6)
    r = max(task.resource_need, 1e-6)
    now = state.now
    mean = max(state.mean_est, 1e-6)
    slack = task.due - p - now
    if slack <= 0.0:
        urgency = (1.0 - slack / max(k * mean, 1e-6)) ** a
        if urgency < 0.0:
            urgency = 0.0
    else:
        urgency = 1.0 / (1.0 + slack / max(k * mean, 1e-6)) ** a
    free = max(state.free, 1e-6)
    fit = (free / r) ** b
    return task.weight * urgency * fit / (p * (r ** rho))

import math
def priority(task, state, k=0.5, m=2.0, rho=0.0):
    p = max(task.estimated_runtime, 1e-6)
    r = max(task.resource_need, 1e-6)
    now = state.now
    mean = max(state.mean_est, 1e-6)
    slack = task.due - p - now
    if slack > 0.0:
        return task.weight * math.exp(-slack / max(k * mean, 1e-6)) / (p * (r ** rho))
    else:
        v = (task.due + p - now) / (2.0 * p)
        if v < 0.0:
            v = 0.0
        if v > 1.0:
            v = 1.0
        late = -slack
        return task.weight * v * (1.0 + m * late / p) / (p * (r ** rho))

