import math
def priority(task, state, k=1.0, alpha=1.0):
    est = max(task.estimated_runtime, 1e-6)
    slack = max(0.0, task.due - est - state.now)
    urgency = math.exp(-slack / (k * max(state.mean_est, 1e-6)))
    remaining = (task.due + est - state.now) / (2.0 * est)
    remaining = max(0.0, min(1.0, remaining))
    return task.weight / est * urgency * (remaining ** alpha)
