import math
def priority(task, state, k=1.0, beta=0.0):
    est = max(task.estimated_runtime, 1e-6)
    res = max(task.resource_need, 1e-6)
    due = task.due
    def val(t):
        return max(0.0, min(1.0, (due + est - t) / (2.0 * est)))
    delta = max(k, 1e-6) * max(state.mean_est, 1e-6)
    v_now = val(state.now)
    v_delay = val(state.now + delta)
    loss = max(0.0, v_now - v_delay)
    return task.weight * loss / (est * (res ** beta))

