    res = max(task.resource_need, 1e-6)
    due = task.due
    mean_est = max(state.mean_est, 1e-6)
    expected_wait = state.queue_work / max(state.free, 1e-6)
    delta = max(k, 1e-6) * max(mean_est, est) + max(gamma, 1e-6) * expected_wait
    def val(t):
        return max(0.0, min(1.0, (due + est - t) / (2.0 * est)))
    v_now = val(state.now)
    v_delay = val(state.now + delta)
    loss = max(0.0, v_now - v_delay)
    tier = m if task.tenant == 'premium' else 1.0
    type_mult = 1.0
