import math
def priority(task, state, a=1.0, b=0.5):
    est = max(task.estimated_runtime, 1e-6)
    now = state.now
    if now > task.due + 2.0 * est:
        return -1e9
    if now + est > task.due:
        return a * task.weight / est
    return -task.due + b * task.weight / est

import math
def priority(task, state, a=1.0, b=10.0):
    est = max(task.estimated_runtime, 1e-6)
    now = state.now
    if now > task.due + 2.0 * est:
        return -1e9
    base = -max(task.due, now + est)
    if state.queue_len > b:
        return base
    else:
        return base + a * task.weight / est

import math
def priority(task, state, a=1.0, b=1.0, k=1.0, c=0.0):
    est = max(task.estimated_runtime, 1e-6)
    r = max(task.resource_need, 1e-6)
    now = state.now
    due = task.due
    if now > due + 2.0 * est:
        return -1e9

    def value_at(s):
        f = s + est
        if f <= due:
            return task.weight
        if f >= due + 2.0 * est:
            return 0.0
        return task.weight * (due + 2.0 * est - f) / (2.0 * est)

    v0 = value_at(now)
    wait = max(0.0, state.queue_work / max(state.free, 1e-6) * k)
    wait = min(wait, 1e6)
    vw = value_at(now + wait)
    loss = max(0.0, v0 - vw)
    density = task.weight / (est * r)
    return a * loss / r + b * density + c * v0 / est - max(due, now + est)

